// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Reverter helper;

    function setUp() public { c = new ReentrancyDAO(); helper = new Reverter(address(c)); }

    function testFuzz_property(uint96 amount) public {
        uint256 amt = bound(uint256(amount), 1, type(uint96).max);
        vm.deal(address(helper), amt);
        helper.deposit(amt);
        uint256 balBefore = address(c).balance;
        bool ok;
        (ok, ) = address(helper).call(abi.encodeWithSignature("withdraw()"));
        // Reference: failed payout reverts -> ok is false, contract keeps its ether.
        // Mutant: withdrawAll completes without reverting and drains contract ether.
        assertTrue(!ok && address(c).balance == balBefore);
    }
}

contract Reverter {
    ReentrancyDAO c;
    constructor(address target) { c = ReentrancyDAO(target); }
    function deposit(uint256 amt) external payable { c.deposit{value: amt}(); }
    function withdraw() external { c.withdrawAll(); }
    fallback() external payable { revert(); }
}
